import os
import sys

def solve():
    if os.path.exists("censor.in"):
        tokens = open("censor.in").read().split()
    else:
        tokens = sys.stdin.read().split()
    s, t = tokens[0], tokens[1]
    m = len(t)
    t_list = list(t)
    last_ch = t[-1]
    stack = []
    for ch in s:
        stack.append(ch)
        if ch == last_ch and len(stack) >= m and stack[-m:] == t_list:
            del stack[-m:]
    ans = "".join(stack)
    if os.path.exists("censor.in"):
        with open("censor.out", "w") as f:
            f.write(ans + "\n")
    else:
        print(ans)

if __name__ == "__main__":
    solve()

