#include <cstdio>
#include <iostream>
#include <string>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    if (FILE* f = fopen("censor.in", "r")) {
        fclose(f);
        freopen("censor.in", "r", stdin);
        freopen("censor.out", "w", stdout);
    }
    string s, t;
    cin >> s >> t;
    string r;
    r.reserve(s.size());
    size_t m = t.size();
    for (char ch : s) {
        r.push_back(ch);
        if (r.size() >= m && r.compare(r.size() - m, m, t) == 0) {
            r.resize(r.size() - m);
        }
    }
    cout << r << '\n';
    return 0;
}

