import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        File inFile = new File("censor.in");
        BufferedReader br = inFile.exists()
            ? new BufferedReader(new FileReader(inFile))
            : new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine().trim();
        String t = br.readLine().trim();
        int m = t.length();
        char lastChar = t.charAt(m - 1);
        StringBuilder sb = new StringBuilder(s.length());
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            sb.append(ch);
            if (ch == lastChar && sb.length() >= m) {
                int start = sb.length() - m;
                boolean match = true;
                for (int k = 0; k < m; k++) {
                    if (sb.charAt(start + k) != t.charAt(k)) {
                        match = false;
                        break;
                    }
                }
                if (match) sb.setLength(start);
            }
        }
        if (inFile.exists()) {
            try (PrintWriter pw = new PrintWriter(new FileWriter("censor.out"))) {
                pw.println(sb.toString());
            }
        } else {
            System.out.println(sb.toString());
        }
    }
}

